Object.assign(SNIP,{});PRESET_NOTES["l36"]={"Ví dụ: Chèn các khóa vào BST": "Mỗi khóa đi từ gốc xuống: nhỏ hơn thì sang trái, lớn hơn thì sang phải, tới chỗ trống thì thành nút mới. Thứ tự chèn này cho cây cân đối 3 tầng. Duyệt giữa in ra dãy tăng: 20 30 40 50 60 70 80.", "Ví dụ: Tìm một khóa": "cur đi 50 → 70 → 60: hai bước là tìm thấy. Mỗi bước bỏ hẳn một cây con, như tìm kiếm nhị phân. Thử đổi x thành 65: cur đi 50 → 70 → 60 → rỗng, không có.", "Ví dụ: Xóa nút có hai con": "Xóa 50: nhỏ nhất của cây con phải là 60, nên 60 được chép lên gốc, rồi nút 60 cũ (lá) bị xóa. Cây vẫn là BST: 60 lớn hơn mọi khóa bên trái, nhỏ hơn mọi khóa còn lại bên phải. Duyệt trước: 60 30 20 40 70 80.", "Ví dụ: Chèn dãy đã sắp xếp làm cây suy biến": "Mỗi khóa mới lớn hơn mọi khóa cũ nên luôn đi sang phải tới cuối: cây thành một đường thẳng 7 tầng, tìm kiếm tốn O(n) như danh sách. Đây là lý do thư viện dùng cây tự cân bằng.", "Lỗi: gán nút mới vào tham số": "u là bản sao của con trỏ được truyền vào: gán u = new Node(x) không làm root (hay u->left của cha) thay đổi. Cây vẫn rỗng. Sửa: cho hàm trả về gốc mới và gán lại (root = chen(root, x), u->left = chen(u->left, x)) như các ví dụ trên."};EX_HINTS["l36"]=[["Chèn: cây rỗng thì nút mới là gốc. Ngược lại đi từ gốc; x nhỏ hơn thì sang trái, không thì sang phải; tới khi con cần đi là nullptr thì gắn nút mới vào đó.", "Dãy tăng dần làm cây thành đường thẳng sâu n tầng: chèn bằng vòng lặp để khỏi đệ quy quá sâu (trình mô phỏng C++ dừng ở 3 000 tầng).", "Số tầng: cao(nullptr) = 0, cao(u) = 1 + max(cao(trái), cao(phải))."], ["Chỉ so mỗi nút với cha là sai (xem ví dụ trong bài). Mỗi nút phải nằm trong một khoảng (lo, hi) do mọi tổ tiên quy định.", "Đi xuống con trái: khoảng thành (lo, v[u]); xuống con phải: (v[u], hi).", "Cách khác: duyệt giữa và kiểm tra dãy thu được tăng dần."], ["Nút có khóa ≥ x là một ứng viên: ghi lại, rồi sang trái xem còn khóa nhỏ hơn mà vẫn ≥ x không.", "Nút có khóa < x: đáp án (nếu có) nằm bên phải.", "Ứng viên ghi sau cùng là đáp án; không có ứng viên nào thì −1. Tốn O(chiều cao)."]];
/* ===================== BÀI 36 · Cây nhị phân tìm kiếm (BST) ===================== */
/* Bài 36 · Cây nhị phân tìm kiếm (BST)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR36=[{label:"Ví dụ: Chèn các khóa vào BST",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* chen(Node* u, int x) {          // trả về gốc mới của cây con\n    if (u == nullptr) return new Node(x);\n    if (x < u->val) u->left = chen(u->left, x);\n    else u->right = chen(u->right, x);\n    return u;\n}\n\nvoid giua(Node* u) {\n    if (u == nullptr) return;\n    giua(u->left);\n    cout << u->val << \" \";\n    giua(u->right);\n}\n\nint main() {\n    int a[7] = {50, 30, 70, 20, 40, 60, 80};\n    Node* root = nullptr;\n    for (int i = 0; i < 7; i++) root = chen(root, a[i]);\n    giua(root);\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u"]}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef chen(u, x):              # trả về gốc mới của cây con\n    if u is None:\n        return Node(x)\n    if x < u.val:\n        u.left = chen(u.left, x)\n    else:\n        u.right = chen(u.right, x)\n    return u\n\ndef giua(u, out):\n    if u is None:\n        return\n    giua(u.left, out)\n    out.append(u.val)\n    giua(u.right, out)\n\nroot = None\nfor x in [50, 30, 70, 20, 40, 60, 80]:\n    root = chen(root, x)\nout = []\ngiua(root, out)\nprint(*out)"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static Node Chen(Node u, int x)          // trả về gốc mới của cây con\n    {\n        if (u == null) return new Node(x);\n        if (x < u.Val) u.Left = Chen(u.Left, x);\n        else u.Right = Chen(u.Right, x);\n        return u;\n    }\n\n    static void Giua(Node u)\n    {\n        if (u == null) return;\n        Giua(u.Left);\n        Console.Write(u.Val + \" \");\n        Giua(u.Right);\n    }\n\n    static void Main()\n    {\n        int[] a = { 50, 30, 70, 20, 40, 60, 80 };\n        Node root = null;\n        foreach (int k in a) root = Chen(root, k);\n        Giua(root);\n        Console.WriteLine();\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u"]}]}},{label:"Ví dụ: Tìm một khóa",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* chen(Node* u, int x) {          // trả về gốc mới của cây con\n    if (u == nullptr) return new Node(x);\n    if (x < u->val) u->left = chen(u->left, x);\n    else u->right = chen(u->right, x);\n    return u;\n}\n\nint main() {\n    int a[7] = {50, 30, 70, 20, 40, 60, 80};\n    Node* root = nullptr;\n    for (int i = 0; i < 7; i++) root = chen(root, a[i]);\n    int x = 60, buoc = 0;\n    Node* cur = root;\n    while (cur != nullptr && cur->val != x) {\n        buoc++;\n        if (x < cur->val) cur = cur->left;\n        else cur = cur->right;\n    }\n    cout << (cur != nullptr ? \"co\" : \"khong\") << \" \" << buoc << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["cur"]}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef chen(u, x):              # trả về gốc mới của cây con\n    if u is None:\n        return Node(x)\n    if x < u.val:\n        u.left = chen(u.left, x)\n    else:\n        u.right = chen(u.right, x)\n    return u\n\nroot = None\nfor x in [50, 30, 70, 20, 40, 60, 80]:\n    root = chen(root, x)\n\nx, buoc = 60, 0\ncur = root\nwhile cur is not None and cur.val != x:\n    buoc += 1\n    cur = cur.left if x < cur.val else cur.right\nprint(\"co\" if cur is not None else \"khong\", buoc)"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static Node Chen(Node u, int x)          // trả về gốc mới của cây con\n    {\n        if (u == null) return new Node(x);\n        if (x < u.Val) u.Left = Chen(u.Left, x);\n        else u.Right = Chen(u.Right, x);\n        return u;\n    }\n\n    static void Main()\n    {\n        int[] a = { 50, 30, 70, 20, 40, 60, 80 };\n        Node root = null;\n        foreach (int k in a) root = Chen(root, k);\n        int x = 60, buoc = 0;\n        Node cur = root;\n        while (cur != null && cur.Val != x)\n        {\n            buoc++;\n            cur = x < cur.Val ? cur.Left : cur.Right;\n        }\n        Console.WriteLine((cur != null ? \"co\" : \"khong\") + \" \" + buoc);\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["cur"]}]}},{label:"Ví dụ: Xóa nút có hai con",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* chen(Node* u, int x) {          // trả về gốc mới của cây con\n    if (u == nullptr) return new Node(x);\n    if (x < u->val) u->left = chen(u->left, x);\n    else u->right = chen(u->right, x);\n    return u;\n}\n\nNode* xoa(Node* u, int x) {\n    if (u == nullptr) return nullptr;\n    if (x < u->val) u->left = xoa(u->left, x);\n    else if (x > u->val) u->right = xoa(u->right, x);\n    else {\n        if (u->left == nullptr) { Node* r = u->right; delete u; return r; }\n        if (u->right == nullptr) { Node* l = u->left; delete u; return l; }\n        Node* m = u->right;                   // nhỏ nhất của cây con phải\n        while (m->left != nullptr) m = m->left;\n        u->val = m->val;                      // chép khóa lên\n        u->right = xoa(u->right, m->val);     // xóa nút nhỏ nhất kia\n    }\n    return u;\n}\n\nvoid truoc(Node* u) {\n    if (u == nullptr) return;\n    cout << u->val << \" \";\n    truoc(u->left);\n    truoc(u->right);\n}\n\nint main() {\n    int a[7] = {50, 30, 70, 20, 40, 60, 80};\n    Node* root = nullptr;\n    for (int i = 0; i < 7; i++) root = chen(root, a[i]);\n    root = xoa(root, 50);       // xóa gốc, có hai con\n    truoc(root);\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u","m"]}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef chen(u, x):              # trả về gốc mới của cây con\n    if u is None:\n        return Node(x)\n    if x < u.val:\n        u.left = chen(u.left, x)\n    else:\n        u.right = chen(u.right, x)\n    return u\n\ndef xoa(u, x):\n    if u is None:\n        return None\n    if x < u.val:\n        u.left = xoa(u.left, x)\n    elif x > u.val:\n        u.right = xoa(u.right, x)\n    else:\n        if u.left is None:\n            return u.right\n        if u.right is None:\n            return u.left\n        m = u.right                    # nhỏ nhất của cây con phải\n        while m.left is not None:\n            m = m.left\n        u.val = m.val                  # chép khóa lên\n        u.right = xoa(u.right, m.val)  # xóa nút nhỏ nhất kia\n    return u\n\ndef truoc(u, out):\n    if u is None:\n        return\n    out.append(u.val)\n    truoc(u.left, out)\n    truoc(u.right, out)\n\nroot = None\nfor x in [50, 30, 70, 20, 40, 60, 80]:\n    root = chen(root, x)\nroot = xoa(root, 50)        # xóa gốc, có hai con\nout = []\ntruoc(root, out)\nprint(*out)"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static Node Chen(Node u, int x)          // trả về gốc mới của cây con\n    {\n        if (u == null) return new Node(x);\n        if (x < u.Val) u.Left = Chen(u.Left, x);\n        else u.Right = Chen(u.Right, x);\n        return u;\n    }\n\n    static Node Xoa(Node u, int x)\n    {\n        if (u == null) return null;\n        if (x < u.Val) u.Left = Xoa(u.Left, x);\n        else if (x > u.Val) u.Right = Xoa(u.Right, x);\n        else\n        {\n            if (u.Left == null) return u.Right;\n            if (u.Right == null) return u.Left;\n            Node m = u.Right;                   // nhỏ nhất của cây con phải\n            while (m.Left != null) m = m.Left;\n            u.Val = m.Val;                      // chép khóa lên\n            u.Right = Xoa(u.Right, m.Val);      // xóa nút nhỏ nhất kia\n        }\n        return u;\n    }\n\n    static void Truoc(Node u)\n    {\n        if (u == null) return;\n        Console.Write(u.Val + \" \");\n        Truoc(u.Left);\n        Truoc(u.Right);\n    }\n\n    static void Main()\n    {\n        int[] a = { 50, 30, 70, 20, 40, 60, 80 };\n        Node root = null;\n        foreach (int k in a) root = Chen(root, k);\n        root = Xoa(root, 50);       // xóa gốc, có hai con\n        Truoc(root);\n        Console.WriteLine();\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u","m"]}]}},{label:"Ví dụ: Chèn dãy đã sắp xếp làm cây suy biến",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* chen(Node* u, int x) {          // trả về gốc mới của cây con\n    if (u == nullptr) return new Node(x);\n    if (x < u->val) u->left = chen(u->left, x);\n    else u->right = chen(u->right, x);\n    return u;\n}\n\nint cao(Node* u) {\n    if (u == nullptr) return 0;\n    return 1 + max(cao(u->left), cao(u->right));\n}\n\nint main() {\n    Node* root = nullptr;\n    for (int x = 1; x <= 7; x++) root = chen(root, x);\n    cout << cao(root) << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root"}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef chen(u, x):              # trả về gốc mới của cây con\n    if u is None:\n        return Node(x)\n    if x < u.val:\n        u.left = chen(u.left, x)\n    else:\n        u.right = chen(u.right, x)\n    return u\n\ndef cao(u):\n    if u is None:\n        return 0\n    return 1 + max(cao(u.left), cao(u.right))\n\nroot = None\nfor x in range(1, 8):\n    root = chen(root, x)\nprint(cao(root))"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static Node Chen(Node u, int x)          // trả về gốc mới của cây con\n    {\n        if (u == null) return new Node(x);\n        if (x < u.Val) u.Left = Chen(u.Left, x);\n        else u.Right = Chen(u.Right, x);\n        return u;\n    }\n\n    static int Cao(Node u)\n    {\n        if (u == null) return 0;\n        return 1 + Math.Max(Cao(u.Left), Cao(u.Right));\n    }\n\n    static void Main()\n    {\n        Node root = null;\n        for (int x = 1; x <= 7; x++) root = Chen(root, x);\n        Console.WriteLine(Cao(root));\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val"}]}},{label:"Lỗi: gán nút mới vào tham số",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nvoid chen(Node* u, int x) {\n    if (u == nullptr) {\n        u = new Node(x);       // chỉ đổi bản sao u trong hàm này\n        return;\n    }\n    if (x < u->val) chen(u->left, x);\n    else chen(u->right, x);\n}\n\nint main() {\n    Node* root = nullptr;\n    chen(root, 5);\n    chen(root, 3);\n    cout << (root == nullptr ? \"cay rong\" : \"co nut\") << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u"]}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef chen(u, x):\n    if u is None:\n        u = Node(x)          # chỉ đổi biến u trong hàm này\n        return\n    if x < u.val:\n        chen(u.left, x)\n    else:\n        chen(u.right, x)\n\nroot = None\nchen(root, 5)\nchen(root, 3)\nprint(\"cay rong\" if root is None else \"co nut\")",note:"u là biến cục bộ của hàm: gán u = Node(x) không làm root (hay u.left của cha) thay đổi. Cây vẫn rỗng. Sửa: cho hàm trả về gốc mới và gán lại (root = chen(root, x), u.left = chen(u.left, x))."},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static void Chen(Node u, int x)\n    {\n        if (u == null)\n        {\n            u = new Node(x);       // chỉ đổi tham số u trong hàm này\n            return;\n        }\n        if (x < u.Val) Chen(u.Left, x);\n        else Chen(u.Right, x);\n    }\n\n    static void Main()\n    {\n        Node root = null;\n        Chen(root, 5);\n        Chen(root, 3);\n        Console.WriteLine(root == null ? \"cay rong\" : \"co nut\");\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u"]}],note:"Tham số u nhận bản sao của tham chiếu: gán u = new Node(x) không làm root (hay u.Left của cha) thay đổi. Cây vẫn rỗng. Sửa: cho hàm trả về gốc mới và gán lại (root = Chen(root, x), u.Left = Chen(u.Left, x))."}}];
